sp_widget.client_script:
api.controller = function($scope) {
    var c = this;

    c.form = {
        hallId: '',
        startDate: '',
        endDate: '',
        purpose: ''
    };

    c.availabilityMessage = '';
    c.isAvailable = false;
    c.successMessage = '';
    c.errorMessage = '';

    // Read URL parameters on load
    function getUrlParam(name) {
        var url = window.location.search;
        var params = new URLSearchParams(url);
        return params.get(name);
    }

    // Auto-fill from URL params
    var hallId = getUrlParam('hallId');
    var startDate = getUrlParam('startDate');
    var endDate = getUrlParam('endDate');

    if (hallId) c.form.hallId = hallId;
    if (startDate) c.form.startDate = decodeURIComponent(startDate);
    if (endDate) c.form.endDate = decodeURIComponent(endDate);

    c.checkAvailability = function() {
        c.availabilityMessage = '';
        c.isAvailable = false;

        if (!c.form.hallId || !c.form.startDate || !c.form.endDate) {
            c.availabilityMessage = 'Please select a hall, start date, and end date first.';
            return;
        }

        var start = new Date(c.form.startDate);
        var end = new Date(c.form.endDate);

        if (end <= start) {
            c.availabilityMessage = 'End Date must be after Start Date.';
            return;
        }

        c.server.get({
            action: 'checkAvailability',
            hallId: c.form.hallId,
            startDate: c.form.startDate,
            endDate: c.form.endDate
        }).then(function(response) {
            if (response.data.availability == 'available') {
                c.availabilityMessage = 'Hall is available for your selected dates!';
                c.isAvailable = true;
            } else {
                c.availabilityMessage = 'Sorry, this hall is already booked for the selected time.';
                c.isAvailable = false;
            }
            $scope.$apply();
        });
    };

    c.submitBooking = function() {
        if (!c.isAvailable) {
            c.errorMessage = 'Please check availability first.';
            return;
        }

        c.server.get({
            action: 'submitBooking',
            hallId: c.form.hallId,
            startDate: c.form.startDate,
            endDate: c.form.endDate,
            purpose: c.form.purpose
        }).then(function(response) {
            if (response.data.result == 'success') {
                c.successMessage = 'Booking submitted! Reference: ' + response.data.number;
                c.errorMessage = '';
                c.form = { hallId: '', startDate: '', endDate: '', purpose: '' };
                c.isAvailable = false;
                c.availabilityMessage = '';
            } else {
                c.errorMessage = 'Error submitting booking. Please try again.';
            }
            $scope.$apply();
        });
    };

    $scope.$on('hallSelected', function(event, data) {
        c.form.hallId = data.hallId;
        if (data.startDate) c.form.startDate = data.startDate;
        if (data.endDate) c.form.endDate = data.endDate;
        $scope.$apply();
    });
};

sp_widget.css:
.booking-form-container {
  padding: 25px;
  background: white;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);

  h3 {
    color: #00695C;
    font-weight: bold;
    margin-bottom: 20px;
    padding-bottom: 10px;
    border-bottom: 2px solid #00695C;
  }

  label {
    color: #333;
    font-size: 13px;
    margin-bottom: 5px;
  }

  .form-control {
    border-radius: 8px;
    border: 1px solid #ddd;

    &:focus {
      border-color: #00695C;
      box-shadow: 0 0 5px rgba(0,105,92,0.3);
    }
  }

  .btn-info {
    background: #00838F;
    border: none;
    border-radius: 20px;
    padding: 8px 20px;

    &:hover {
      background: #006064;
    }
  }

  .btn-primary {
    background: #00695C;
    border: none;
    border-radius: 8px;
    padding: 12px;
    font-size: 15px;
    font-weight: bold;
    margin-top: 10px;

    &:hover {
      background: #004D40;
    }

    &:disabled {
      background: #B2DFDB;
      cursor: not-allowed;
    }
  }
}

sp_widget.script:
(function() {
    // Handle availability check
    if (input && input.action == 'checkAvailability') {
        var hallId = input.hallId;
        var startDate = input.startDate;
        var endDate = input.endDate;

        gs.info('Checking: hall=' + hallId + ' start=' + startDate + ' end=' + endDate);

        var checkGr = new GlideRecord('x_1954179_sports_0_sports_hall_booking');
        checkGr.addQuery('sports_hall', hallId);
        checkGr.addQuery('status', 'Approved');
        checkGr.query();

        var isBooked = false;
        while (checkGr.next()) {
            var existingStart = checkGr.getValue('start_date');
            var existingEnd = checkGr.getValue('end_date');
            gs.info('Existing: ' + existingStart + ' to ' + existingEnd);
            if (startDate < existingEnd && endDate > existingStart) {
                isBooked = true;
                break;
            }
        }

        data.availability = isBooked ? 'unavailable' : 'available';
        gs.info('Result: ' + data.availability);
        return;
    }

    // Handle booking submission
    if (input && input.action == 'submitBooking') {
        var bookGr = new GlideRecord('x_1954179_sports_0_sports_hall_booking');
        bookGr.initialize();
        bookGr.setValue('sports_hall', input.hallId);
        bookGr.setValue('requested_by', gs.getUserID());
        bookGr.setValue('start_date', input.startDate);
        bookGr.setValue('end_date', input.endDate);
        bookGr.setValue('purpose', input.purpose);
        bookGr.setValue('status', 'Pending');
        var sysId = bookGr.insert();

        if (sysId) {
            var confirmGr = new GlideRecord('x_1954179_sports_0_sports_hall_booking');
            confirmGr.get(sysId);
            data.result = 'success';
            data.number = confirmGr.getValue('number');
        } else {
            data.result = 'error';
        }
        return;
    }

    // Load ALL sports halls for dropdown
    var gr = new GlideRecord('x_1954179_sports_0_sports_hall');
    gr.orderBy('hall_name');
    gr.query();

    data.halls = [];
    while (gr.next()) {
        data.halls.push({
            sys_id: gr.getUniqueValue(),
            name: gr.getValue('hall_name')
        });
    }
})();
